"""Publish complete experimental Java and a verified selected-source-to-overlay patch.

Run after the new source package is final. Uses private Git indexes/objects only;
does not compile, change selected source, or claim a production promotion.
"""

import argparse
import hashlib
import json
from pathlib import Path
import runpy
import shutil
import tempfile

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
PHASE = 'result-coordinate-evidence/publication-followup'
MATERIALIZER = 'core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer.java'
SELECTED_SHA = 'cb0749719313b85c8cd134b6c03085f712915188f0e53333cbd46e19e2f0f96e'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo', type=Path, default=ROOT)
    parser.add_argument('--source-delivery', type=Path, required=True)
    parser.add_argument('--runtime-descriptor', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    delivery = args.source_delivery.resolve(strict=True)
    descriptor_path = args.runtime_descriptor.resolve(strict=True)
    output = args.output.parent.resolve(strict=True) / args.output.name
    helper = repo / PHASE / 'delivery/build-turn-delta.py'
    api = runpy.run_path(str(helper))
    require, git = api['require'], api['git']
    require(not output.exists() and not output.is_relative_to(repo) and not output.is_relative_to(delivery),
            'Output must be new and outside both the checkout and the source package')
    require(descriptor_path.is_relative_to(repo / PHASE), 'Runtime descriptor must belong to this phase')
    inputs = {}
    selected = api['load_receipt'](delivery, inputs, False)
    descriptor_data = api['read_stable'](descriptor_path, inputs)
    descriptor = json.loads(descriptor_data)
    require(descriptor['diagnosticOnly'] is False and descriptor['noProductionPromotion']
            and descriptor['selectedProductionSourceSha256'] == SELECTED_SHA,
            'Expected the frozen original-page publication experiment')

    def pinned_file(key):
        path = Path(descriptor[key]).resolve(strict=True)
        require(path.is_relative_to(repo / PHASE), 'Experimental input escaped this phase')
        data = api['read_stable'](path, inputs)
        require(hashlib.sha256(data).hexdigest() == descriptor[key + 'Sha256'], 'Changed input: ' + key)
        return path, data

    overlay_path, overlay = pinned_file('overlaySourceFile')
    _, generator_patch = pinned_file('overlayPatchFile')
    _, source_generation = pinned_file('sourceGenerationFile')
    _, validation = pinned_file('validationFile')
    generation = json.loads(source_generation)
    require(generation['sourceSha256'] == SELECTED_SHA
            and generation['generatedSourceSha256'] == hashlib.sha256(overlay).hexdigest()
            and generation['unchangedMaterializerBodyExceptEntryGuard']
            and generation['ordinaryReuseUnchanged'] and generation['coordinateTransportUnchanged']
            and generation['ownershipAndCleanupUnchanged'] and generation['productionSourceWritten'] is False,
            'Source generation does not preserve the experiment contract')
    environment = api['git_environment']()
    head_before = git(repo, ['rev-parse', '--verify', 'HEAD'], environment)

    def git_path(name):
        path = Path(git(repo, ['rev-parse', '--git-path', name], environment).decode().strip())
        return (path if path.is_absolute() else repo / path).resolve()

    real_index = git_path('index')
    index_before = (real_index.exists(), api['file_hash'](real_index) if real_index.exists() else None)
    original_objects = git_path('objects')
    staging = Path(tempfile.mkdtemp(prefix='.selected-publication-overlay-', dir=output.parent))
    published = False
    try:
        with tempfile.TemporaryDirectory(prefix='rdf4j-selected-publication-overlay-') as private_name:
            private = Path(private_name)
            objects = private / 'objects'
            objects.mkdir()

            def isolated(name):
                return environment | {'GIT_INDEX_FILE': str(private / (name + '.index')),
                    'GIT_OBJECT_DIRECTORY': str(objects),
                    'GIT_ALTERNATE_OBJECT_DIRECTORIES': str(original_objects)}

            selected_env = isolated('selected')
            git(repo, ['read-tree', api['BASE_COMMIT']], selected_env)
            git(repo, ['apply', '--cached', '--binary', '--whitespace=nowarn', '-'], selected_env, selected['patch'])
            selected_tree = git(repo, ['write-tree'], selected_env).decode().strip()
            require(selected_tree == selected['summary']['snapshot_tree'], 'Reconstructed selected tree differs')
            entries = api['tree_entries'](repo, selected_tree, selected_env)
            manifest = {entry['path']: entry for entry in selected['manifest']['entries']}
            selected_source = git(repo, ['cat-file', 'blob', selected_tree + ':' + MATERIALIZER], selected_env)
            require(hashlib.sha256(selected_source).hexdigest() == manifest[MATERIALIZER]['sha256'] == SELECTED_SHA,
                    'Selected materializer is not the preserved original')
            require(api['read_stable'](repo / MATERIALIZER, inputs) == selected_source,
                    'Active production source differs from the delivered selected tree')
            generated_relative = overlay_path.relative_to(repo).as_posix()
            require(manifest[generated_relative]['sha256'] == hashlib.sha256(overlay).hexdigest(),
                    'Source delivery omitted or changed the complete experimental materializer')

            target_env = isolated('overlay')
            git(repo, ['read-tree', selected_tree], target_env)
            oid = git(repo, ['hash-object', '-w', '--stdin'], target_env, overlay).decode().strip()
            git(repo, ['update-index', '--add', '--cacheinfo', entries[MATERIALIZER][0] + ',' + oid + ',' + MATERIALIZER],
                target_env)
            target_tree = git(repo, ['write-tree'], target_env).decode().strip()
            target_entries = api['tree_entries'](repo, target_tree, target_env)
            changed = sorted(path for path in entries.keys() | target_entries.keys()
                             if entries.get(path) != target_entries.get(path))
            require(changed == [MATERIALIZER], 'Experimental patch changes another selected path')
            patch = git(repo, ['diff', '--binary', '--full-index', '--no-color', '--no-ext-diff', '--no-textconv',
                              '--no-renames', '--src-prefix=a/', '--dst-prefix=b/', selected_tree, target_tree, '--'],
                        target_env)
            require(bool(patch), 'Experimental transition is empty')
            for name, candidate_patch in (('git-patch', patch), ('generator-patch', generator_patch)):
                replay = isolated(name)
                git(repo, ['read-tree', selected_tree], replay)
                git(repo, ['apply', '--cached', '--binary', '--whitespace=nowarn', '-'], replay, candidate_patch)
                require(git(repo, ['write-tree'], replay).decode().strip() == target_tree,
                        name + ' does not produce the exact experimental tree')
                require(git(repo, ['cat-file', 'blob', target_tree + ':' + MATERIALIZER], replay) == overlay,
                        'Experimental source bytes differ')
                git(repo, ['apply', '--cached', '--binary', '--reverse', '--whitespace=nowarn', '-'], replay,
                    candidate_patch)
                require(git(repo, ['write-tree'], replay).decode().strip() == selected_tree,
                        name + ' reverse application differs')

            # Every selected Java file in this phase is preserved, including diagnostics, tests and preimages.
            support = {}
            for path in sorted(manifest):
                if not (path.startswith(PHASE + '/') and path.endswith('.java')):
                    continue
                data = git(repo, ['cat-file', 'blob', selected_tree + ':' + path], selected_env)
                require(hashlib.sha256(data).hexdigest() == manifest[path]['sha256'], 'Support Java source differs')
                destination = staging / 'experimental-support' / path
                destination.parent.mkdir(parents=True, exist_ok=True)
                destination.write_bytes(data)
                support[path] = manifest[path]['sha256']
            require(any(path.endswith('/PublicationAblationContractTest.java') for path in support)
                    and any(path.endswith('/PublicationDiagnostics.java') for path in support),
                    'The complete experiment tests/diagnostics were not selected')
            complete = staging / 'production-source' / MATERIALIZER
            complete.parent.mkdir(parents=True)
            complete.write_bytes(overlay)
            (staging / 'selected-to-publication-overlay.patch').write_bytes(patch)
            (staging / 'generator-original.patch').write_bytes(generator_patch)
            (staging / 'runtime-descriptor.json').write_bytes(descriptor_data)
            (staging / 'source-generation.json').write_bytes(source_generation)
            (staging / 'validation.json').write_bytes(validation)
            verification = {'format': 1, 'selectedSourceTree': selected_tree, 'experimentalOverlayTree': target_tree,
                'selectedSourcePackageSummarySha256': selected['summarySha256'], 'changedPaths': changed,
                'selectedSourceSha256': SELECTED_SHA, 'experimentalSourceSha256': hashlib.sha256(overlay).hexdigest(),
                'patchSha256': hashlib.sha256(patch).hexdigest(), 'patchBytes': len(patch),
                'generatorPatchSha256': hashlib.sha256(generator_patch).hexdigest(),
                'bothPatchesForwardExactTreeVerified': True, 'bothPatchesReverseExactTreeVerified': True,
                'completeExperimentalJava': support, 'privateObjectsAndIndexesOnly': True,
                'headUnchanged': True, 'realIndexUnchanged': True, 'javaExecuted': False,
                'helperDependency': str(helper.relative_to(repo)), 'helperDependencySha256': api['file_hash'](helper),
                'candidateSelected': False,
                'acceptedTimingComparison': False,
                'scope': 'One materializer source file in the complete selected source tree; experimental only.'}
            (staging / 'verification.json').write_bytes(api['json_bytes'](verification))
            (staging / 'README.md').write_text(
                '# Complete publication-omission experiment\n\n'
                'Apply selected-to-publication-overlay.patch to the complete selected source archive in this delivery. '
                'It changes exactly NativeResultMaterializer.java. The complete resulting source is in production-source/. '
                'Both this Git patch and the preserved generator patch were applied and reversed as exact Git trees in '
                'private indexes. Selected production remains unchanged.\n\n'
                'experimental-support/ contains every Java file selected from this phase, including the six isolated '
                'contract tests, full diagnostic sources and source preimages. These support sources are not additional '
                'module patches. The source and runtime archives contain their generators and validation runners.\n\n'
                'This is a fixture-specific name-mask counterfactual, not a generic production policy. The fixed timing '
                'study stopped incomplete and supplies no accepted timing ratios. For its recorded binary state, use '
                'the frozen runtime: it prefixes only the outer materializer and plan classes '
                'and retains original nested page/memo class bytes. A fresh full-source compilation is a new runtime '
                'identity and is not claimed byte-equivalent to the preserved experiment.\n', encoding='utf-8')
            products = [path for path in staging.rglob('*') if path.is_file()]
            (staging / 'SHA256SUMS').write_text(''.join(api['file_hash'](path) + '  '
                + path.relative_to(staging).as_posix() + '\n' for path in sorted(products)), encoding='ascii')
        require((real_index.exists(), api['file_hash'](real_index) if real_index.exists() else None) == index_before,
                'Real repository index changed')
        require(git(repo, ['rev-parse', '--verify', 'HEAD'], environment) == head_before, 'Repository HEAD changed')
        for path, before in inputs.items():
            require(api['signature'](path) == before, 'Source package input changed')
        api['publish_no_replace'](staging, output)
        published = True
        print(json.dumps(verification, indent=2, sort_keys=True))
    finally:
        if not published:
            shutil.rmtree(staging)


if __name__ == '__main__':
    main()
